package com.lexia.legalassistant.data.repository

/**
 * Registro oficial estatutario de los 490 Artículos del Código Nacional de Procedimientos Penales (CNPP).
 * Publicado en el Diario Oficial de la Federación, rector del sistema de justicia penal acusatorio y oral mexicano.
 */
object CnppStatutoryData {

    data class ArticleMeta(
        val title: String,
        val category: String,
        val summary: String
    )

    val articles: Map<Int, ArticleMeta> = mapOf(
        1 to ArticleMeta("Ámbito de Aplicación Territorial y Fuero", "Principios Procesales", "Las disposiciones de este Código son de orden público y de observancia general en toda la República Mexicana, para los delitos que sean competencia de los órganos jurisdiccionales federales y locales."),
        2 to ArticleMeta("Objeto del Código Nacional", "Principios Procesales", "Esclarecer los hechos, proteger al inocente, procurar que el culpable no quede impune y que los daños causados por el delito se reparen."),
        3 to ArticleMeta("Glosario de Términos Legales Procesales", "Principios Procesales", "Definiciones auténticas de asesor jurídico, audiencia, Consejo, defensor, juez de control, Ministerio Público, policía, procuraduría y tribunal de enjuiciamiento."),
        4 to ArticleMeta("Características y Principios Rectores", "Principios Procesales", "El proceso penal será acusatorio y oral, en él se observarán los principios de publicidad, contradicción, concentración, continuidad e inmediación."),
        5 to ArticleMeta("Principio de Publicidad de las Audiencias", "Principios Procesales", "Las audiencias serán públicas con el fin de que a ellas accedan no sólo las partes sino también los medios de comunicación y la sociedad en general con las excepciones legales."),
        6 to ArticleMeta("Principio de Contradicción Probatoria", "Principios Procesales", "Las partes podrán conocer, controvertir o confrontar los medios de prueba, así como oponerse a las peticiones y alegatos de la otra parte."),
        7 to ArticleMeta("Principio de Continuidad de Actuaciones", "Principios Procesales", "Las audiencias se llevarán a cabo de forma continua, sucesiva y secuencial, salvo los casos de suspensión o receso previstos taxativamente en este Código."),
        8 to ArticleMeta("Principio de Concentración Procesal", "Principios Procesales", "Las audiencias se desarrollarán preferentemente en un mismo día o en días consecutivos hasta su conclusión para asegurar agilidad procesal."),
        9 to ArticleMeta("Principio de Inmediación Judicial Estricta", "Principios Procesales", "Toda audiencia se desarrollará íntegramente en presencia del Órgano jurisdiccional; en ningún caso podrá delegar en persona alguna el desahogo o valoración."),
        10 to ArticleMeta("Principio de Igualdad ante la Ley", "Principios Procesales", "Todas las personas son iguales ante la ley y no podrán ser discriminadas por su origen étnico, género, edad, discapacidad o condición social."),
        11 to ArticleMeta("Principio de Igualdad entre las Partes", "Principios Procesales", "Se garantiza a las partes en condiciones de igualdad el pleno e irrestricto ejercicio de las facultades y derechos previstos en la Constitución y tratados."),
        12 to ArticleMeta("Principio de Juicio Previo y Debido Proceso", "Principios Procesales", "Ninguna persona podrá ser condenada a una pena ni sometida a una medida de seguridad, sino en virtud de resolución dictada por un órgano jurisdiccional competente."),
        13 to ArticleMeta("Principio de Presunción de Inocencia", "Principios Procesales", "Toda persona se presume inocente y será tratada como tal en todas las etapas del procedimiento mientras no se declare su responsabilidad mediante sentencia firme."),
        14 to ArticleMeta("Prohibición de Doble Enjuiciamiento (Non Bis In Idem)", "Principios Procesales", "La persona condenada, absuelta o cuyo proceso haya sido sobreseído, no podrá ser sometida a otro proceso penal por los mismos hechos."),
        15 to ArticleMeta("Derecho a la Intimidad y Privacidad", "Principios Procesales", "En todo procedimiento penal se respetará el derecho a la intimidad de las partes y terceros, protegiendo datos personales en diligencias públicas."),
        16 to ArticleMeta("Justicia Pronta y Plazos Constitucionales", "Principios Procesales", "Toda persona tiene derecho a ser juzgada dentro de los plazos legalmente establecidos, garantizando una tutela judicial expedita y sin dilaciones."),
        17 to ArticleMeta("Defensa Técnica Adecuada y Gratuita", "Principios Procesales", "El imputado tendrá derecho a ser defendido por licenciado en derecho con cédula profesional registrada; de no contar con él, se le asignará un defensor público."),
        18 to ArticleMeta("Garantía de Ser Informado de sus Derechos", "Principios Procesales", "Toda persona desde el momento de su detención o comparecencia debe ser informada de manera clara y comprensible de los derechos que le asisten."),
        19 to ArticleMeta("Derecho Inviolable a No Autoincriminarse", "Principios Procesales", "El imputado tiene derecho a guardar silencio o a declarar libremente; su silencio no podrá ser utilizado en su perjuicio ni como indicio de culpabilidad."),
        20 to ArticleMeta("Reglas Generales de Competencia Judicial", "Competencia Penal", "La competencia de los tribunales se determinará por razón de territorio, fuero, materia y grado de conformidad con las leyes orgánicas respectivas."),
        21 to ArticleMeta("Reglas de Competencia Territorial", "Competencia Penal", "Es competente para conocer del proceso el juez del lugar donde se haya cometido el hecho punible o donde haya cesado en caso de delitos continuados."),
        22 to ArticleMeta("Competencia por Conexidad de Delitos", "Competencia Penal", "Cuando se cometan delitos conexos derivados de un mismo propósito o ejecución, conocerá del asunto el juez competente para el delito que merezca mayor pena."),
        23 to ArticleMeta("Vías de Excepción: Declinatoria e Inhibitoria", "Competencia Penal", "Las cuestiones de competencia territorial o de fuero podrán promoverse por declinatoria ante el juez incompetente o por inhibitoria ante el que se estime competente."),
        24 to ArticleMeta("Procedimiento y Efectos de la Declinatoria", "Competencia Penal", "Promovida la declinatoria, el juzgador remitirá los autos inmediatamente al tribunal que considere competente absteniéndose de resolver cuestiones de fondo."),
        25 to ArticleMeta("Facultad de Atracción Federal en Delitos Conexos", "Competencia Penal", "Los tribunales federales podrán conocer de delitos del fuero común cuando tengan conexidad con delitos federales o atenten contra periodistas."),
        26 to ArticleMeta("Competencia en Delitos Cometidos a Bordo de Naves", "Competencia Penal", "Para los delitos cometidos a bordo de buques o aeronaves nacionales, será competente el juez del primer puerto de atraque o aterrizaje en territorio nacional."),
        27 to ArticleMeta("Auxilio Judicial entre Entidades Federativas", "Competencia Penal", "Los órganos jurisdiccionales se prestarán auxilio mutuo para la práctica de notificaciones, aprehensiones o diligencias mediante exhortos y oficios de colaboración."),
        28 to ArticleMeta("Conflictos de Competencia entre Jueces", "Competencia Penal", "Los conflictos competenciales entre jueces del mismo fuero serán resueltos sumariamente por el Tribunal de Alzada que corresponda en cinco días."),
        29 to ArticleMeta("Validez de Actos Procesales Previos a la Incompetencia", "Competencia Penal", "La declaración de incompetencia no anulará los actos procesales de investigación, detención o medidas cautelares practicadas con anterioridad."),
        30 to ArticleMeta("Causas de Impedimento de Jueces y Magistrados", "Competencia Penal", "Los juzgadores penales deberán excusarse de conocer cuando tengan parentesco, enemistad o interés patrimonial directo en el proceso penal."),
        31 to ArticleMeta("Trámite Incidental de la Excusa Judicial", "Competencia Penal", "El juez que advierta una causal de impedimento se excusará de inmediato remitiendo el expediente al sustituto legal sin suspender medidas urgentes."),
        32 to ArticleMeta("Procedimiento de Recusación de Juzgadores", "Competencia Penal", "Las partes podrán recusar con causa fundada a jueces de control o magistrados ofreciendo medios de prueba en la audiencia incidental respectiva."),
        33 to ArticleMeta("Resolución Sumaria del Incidente de Recusación", "Competencia Penal", "La recusación será resuelta por el Tribunal de Alzada dentro de los tres días siguientes tras escuchar los argumentos y pruebas de las partes."),
        34 to ArticleMeta("Efectos Procesales de la Recusación Fundada", "Competencia Penal", "Declarada procedente la recusación, el juzgador quedará definitivamente apartado del conocimiento del proceso penal asumiendo el juez sustituto."),
        35 to ArticleMeta("Sanción por Recusaciones Temerarias o Dilatorias", "Competencia Penal", "Se impondrá multa económica a la parte o defensor que interponga recusaciones manifiestamente infundadas con el fin de dilatar audiencias."),
        36 to ArticleMeta("Incompatibilidad Funcional de Juzgadores", "Competencia Penal", "Ningún juez de control que haya intervenido en la audiencia inicial o intermedia podrá fungir como integrante del tribunal de juicio oral en el mismo caso."),
        37 to ArticleMeta("Competencia de los Jueces de Control", "Competencia Penal", "Los jueces de control conocen desde el inicio de la investigación judicializada hasta el dictado del auto de apertura a juicio oral y salidas alternas."),
        38 to ArticleMeta("Competencia del Tribunal de Enjuiciamiento", "Competencia Penal", "El tribunal de enjuiciamiento colegiado o unitario conoce del desahogo del juicio oral, deliberación, fallo e individualización de sanciones."),
        39 to ArticleMeta("Competencia de los Jueces de Ejecución Penal", "Competencia Penal", "Los jueces de ejecución vigilan y garantizan el cumplimiento de las penas y medidas de seguridad conforme a la Ley Nacional de Ejecución Penal."),
        40 to ArticleMeta("Competencia de los Tribunales de Alzada", "Competencia Penal", "Los tribunales de alzada conocen de los recursos ordinarios de apelación interpuestos contra autos y sentencias de los jueces de primera instancia."),
        41 to ArticleMeta("Distribución Aleatoria de Casos y Turno", "Competencia Penal", "El Consejo de la Judicatura implementará sistemas de gestión electrónica para el turno aleatorio e imparcial de asuntos a los juzgados penales."),
        42 to ArticleMeta("Facultades Disciplinarias del Juez en Audiencias", "Competencia Penal", "El juzgador mantendrá el orden en la sala de audiencias pudiendo imponer correcciones disciplinarias, desalojo de personas y arrestos hasta por 36 horas."),
        43 to ArticleMeta("Medidas de Apremio para Hacer Cumplir Resoluciones", "Competencia Penal", "Para hacer cumplir sus órdenes el juez podrá utilizar: amonestación, multa tasada en UMA, auxilio de la fuerza pública y arresto disciplinario."),
        44 to ArticleMeta("Uso Obligatorio del Idioma Español e Intérpretes", "Actos Procesales", "Los actos procesales se realizarán en idioma español; a las personas indígenas o extranjeras se les proveerá de oficio de traductor o intérprete certificado."),
        45 to ArticleMeta("Lugar y Sede de las Audiencias Judiciales", "Actos Procesales", "Las audiencias se celebrarán en la sala de audiencias del tribunal; excepcionalmente el juez podrá constituirse en otro lugar por necesidad probatoria."),
        46 to ArticleMeta("Oralidad en las Peticiones y Resoluciones", "Actos Procesales", "Las partes formularán sus peticiones, alegatos y defensas de manera oral y directa ante el juez, prohibiéndose la lectura íntegra de memoriales escritos."),
        47 to ArticleMeta("Constancia y Registro Electrónico de Audiencias", "Actos Procesales", "Todas las audiencias se registrarán mediante audio y video digital asegurando su fidelidad, integridad y disponibilidad para consulta de las partes."),
        48 to ArticleMeta("Acceso Restringido a Grabaciones Reservadas", "Actos Procesales", "Las grabaciones de audiencias privadas o con menores de edad tendrán reserva estricta y sólo podrán acceder a ellas las partes acreditadas en juicio."),
        49 to ArticleMeta("Formalidades y Levantamiento de Actas Judiciales", "Actos Procesales", "El secretario de sala levantará un acta sucinta de cada audiencia asentando fecha, asistentes, resoluciones dictadas y protestas formuladas."),
        50 to ArticleMeta("Firma Electrónica y Certificación de Resoluciones", "Actos Procesales", "Las resoluciones judiciales se asentarán por escrito con la firma autógrafa o electrónica avanzada del juzgador que las haya pronunciado."),
        51 to ArticleMeta("Reglas de Comportamiento en la Sala de Juicio", "Actos Procesales", "Los asistentes permanecerán descubiertos, en silencio y con respeto, prohibiéndose el uso de teléfonos celulares o armas en el recinto judicial."),
        52 to ArticleMeta("Asistencia Obligatoria del Ministerio Público y Defensor", "Actos Procesales", "La presencia ininterrumpida del Ministerio Público y del Defensor es requisito de validez procesal en todas las audiencias penales."),
        53 to ArticleMeta("Sustitución Inmediata de Defensores Ausentes", "Actos Procesales", "Si el defensor particular no se presenta a la audiencia, el juez nombrará de inmediato al defensor público para evitar la suspensión del acto."),
        54 to ArticleMeta("Exclusiones Excepcionales de Publicidad", "Actos Procesales", "El tribunal podrá restringir la entrada a la audiencia cuando afecte la intimidad de menores, la seguridad nacional o secretos comerciales protegidos."),
        55 to ArticleMeta("Prohibición de Grabar Audiencias a Particulares", "Actos Procesales", "Queda prohibido a los medios o particulares grabar imágenes o audios dentro de la sala sin autorización judicial expresa del juez presidente."),
        56 to ArticleMeta("Resoluciones Judiciales: Autos y Sentencias", "Actos Procesales", "Las resoluciones judiciales son sentencias si deciden el fondo del juicio; autos si resuelven cuestiones previas, cautelares o procedimentales."),
        57 to ArticleMeta("Deber de Fundamentación y Motivación Judicial", "Actos Procesales", "Todas las resoluciones judiciales deberán ser fundadas y motivadas expresando con claridad las normas legales aplicables y la valoración lógica de los hechos."),
        58 to ArticleMeta("Plazos para Dictar y Notificar Resoluciones", "Actos Procesales", "Las resoluciones orales en audiencia se dictarán de inmediato; los autos por escrito se emitirán dentro de los tres días siguientes a la petición."),
        59 to ArticleMeta("Aclaración de Resoluciones Judiciales", "Actos Procesales", "Las partes podrán solicitar la aclaración de contradicciones o ambigüedades en sentencias o autos dentro de las 24 horas siguientes a su notificación."),
        60 to ArticleMeta("Firmeza y Cosa Juzgada de las Sentencias", "Actos Procesales", "Las sentencias adquieren la calidad de cosa juzgada e inmutabilidad procesal una vez fenecidos los plazos para interponer el recurso de apelación."),
        61 to ArticleMeta("Formalidades para el Desahogo de Notificaciones", "Actos Procesales", "Las notificaciones se practicarán de manera personal, por estrados, por correo electrónico o por medio de los sistemas digitales del tribunal."),
        62 to ArticleMeta("Notificaciones en Audiencia por Estrados Orales", "Actos Procesales", "Las resoluciones pronunciadas en audiencias orales se entenderán notificadas en ese mismo momento a todas las partes presentes o debidamente citadas."),
        63 to ArticleMeta("Notificaciones Personales a Víctimas e Imputados", "Actos Procesales", "Se notificarán personalmente las resoluciones que ordenen citaciones a juicio, vinculación a proceso, medidas cautelares y la sentencia definitiva."),
        64 to ArticleMeta("Práctica de Notificaciones por Medios Electrónicos", "Actos Procesales", "Las notificaciones electrónicas surtirán plenos efectos a partir del momento en que conste el acuse digital de recibo en el buzón judicial autorizado."),
        65 to ArticleMeta("Citatorios Judiciales y Apercibimientos Legales", "Actos Procesales", "Los citatorios para comparecer ante el juez expresarán el objeto de la comparecencia, la fecha y apercibimiento de orden de aprehensión en caso de rebeldía."),
        66 to ArticleMeta("Cómputo Estricto de Términos y Plazos Procesales", "Actos Procesales", "Los plazos empezarán a correr al día siguiente de practicada la notificación; los plazos constitucionales se computarán de momento a momento."),
        67 to ArticleMeta("Habilitación de Días Inhábiles en Audiencia Inicial", "Actos Procesales", "Tratándose de personas detenidas, todos los días y horas son hábiles para resolver su situación jurídica dentro del plazo constitucional de 72 horas."),
        68 to ArticleMeta("Exhortos Nacionales entre Autoridades Penales", "Actos Procesales", "Los exhortos dirigidos a jueces de otras jurisdicciones se diligenciarán sin dilación en un plazo que no excederá de cinco días hábiles."),
        69 to ArticleMeta("Nulidad de Actos Procesales por Violación a Derechos", "Actos Procesales", "Cualquier acto procesal ejecutado con vulneración a derechos fundamentales consagrados en la Constitución o tratados será nulo de pleno derecho."),
        70 to ArticleMeta("Saneamiento y Convalidación de Irregularidades", "Actos Procesales", "Los defectos procesales que no vulneren garantías individuales podrán sanearse de oficio o a petición de parte antes de que cause ejecutoria la etapa."),
        71 to ArticleMeta("Reposición de Actuaciones Judiciales Extraviadas", "Actos Procesales", "En caso de extravío de constancias electrónicas o actas de juicio, se ordenará la reposición inmediata con base en los respaldos audiovisuales del servidor."),
        72 to ArticleMeta("Obligación de Comparecencia de Testigos y Peritos", "Actos Procesales", "Toda persona citada legalmente tiene la obligación ineludible de comparecer a testificar bajo apercibimiento de presentación forzosa con auxilio policial."),
        73 to ArticleMeta("Excepciones al Deber de Declarar Testimonialmente", "Actos Procesales", "No están obligados a declarar: el cónyuge, concubino, ascendientes o descendientes del imputado, así como los ministros religiosos y abogados defensores."),
        74 to ArticleMeta("Protección y Reserva de Identidad a Testigos en Riesgo", "Actos Procesales", "El juez podrá autorizar medidas especiales de protección y distorsión de voz o imagen a favor de testigos protegidos amenazados por el crimen organizado."),
        75 to ArticleMeta("Custodia de Evidencias Materiales en el Tribunal", "Actos Procesales", "Los objetos, armas o evidencias materiales incorporadas a juicio se mantendrán bajo custodia segura del juzgado con rigurosa cadena de custodia."),
        76 to ArticleMeta("Acceso del Imputado a la Carpeta de Investigación", "Actos Procesales", "El imputado y su defensor tienen derecho a consultar y obtener copias gratuitas de todos los registros de la investigación desde el momento de la detención."),
        77 to ArticleMeta("Reserva Ministerial Temporal de la Investigación", "Actos Procesales", "El Ministerio Público sólo podrá reservar actuaciones específicas cuando resulte indispensable para asegurar la captura de otros coautores prófugos."),
        78 to ArticleMeta("Sanción por Filtración Ilícita de Investigaciones", "Actos Procesales", "El servidor público que difunda indebidamente imágenes o datos de carpetas de investigación será sancionado penalmente por violación de deber de sigilo."),
        79 to ArticleMeta("Cooperación Judicial Internacional en Materia Penal", "Actos Procesales", "Las solicitudes de asistencia jurídica internacional y extradición se tramitarán por conducto de la Fiscalía General de la República y la SRE."),
        80 to ArticleMeta("Práctica de Diligencias en el Extranjero", "Actos Procesales", "Las cartas rogatorias remitidas a tribunales foráneos se sujetarán a los convenios bilaterales y multilaterales de cooperación penal suscritos por México."),
        81 to ArticleMeta("Validez Probatoria de Diligencias Extranjeras", "Actos Procesales", "Las pruebas recabadas en el extranjero tendrán valor probatorio si se obtuvieron respetando los derechos humanos y las formalidades del derecho internacional."),
        82 to ArticleMeta("Deber de Imparcialidad y Objetividad del MP", "Actos Procesales", "El Ministerio Público actuará con estricta objetividad y lealtad procesal, debiendo aportar no sólo los datos de cargo sino también los que favorezcan al imputado."),
        83 to ArticleMeta("Facultad de Desistimiento de Pruebas Ofrecidas", "Actos Procesales", "Las partes podrán desistirse libremente de los medios de prueba que hayan ofrecido antes de su desahogo formal en la audiencia de juicio."),
        84 to ArticleMeta("Requerimiento de Auxilio de la Fuerza Pública", "Actos Procesales", "Los jueces y agentes del Ministerio Público podrán ordenar el auxilio de la fuerza pública federal o local para ejecutar cateos y traslados seguros."),
        85 to ArticleMeta("Uso de Videoconferencia en Audiencias Judiciales", "Actos Procesales", "El desahogo de audiencias podrá verificarse mediante videoconferencia en tiempo real cuando el reo esté en penal de máxima seguridad o testigos en el extranjero."),
        86 to ArticleMeta("Requisitos de Seguridad Técnica en Videoconferencias", "Actos Procesales", "La videoconferencia judicial debe garantizar comunicación simultánea, privada y continua entre el imputado y su defensor letrado en todo momento."),
        87 to ArticleMeta("Conservación Periódica de Archivos Digitales", "Actos Procesales", "El sistema judicial mantendrá copias de seguridad redundantes de todas las videograbaciones de juicios orales por el tiempo que prescriba la pena impuesta."),
        88 to ArticleMeta("Acceso Público a Sentencias Definitivas Anonimizadas", "Actos Procesales", "Las sentencias penales definitivas dictadas por los tribunales serán de acceso público en versiones testadas protegiendo datos sensibles de las víctimas."),
        89 to ArticleMeta("Obligación de Notificación a Consulados Extranjeros", "Actos Procesales", "Cuando se detenga a una persona extranjera, la autoridad notificará de inmediato al consulado de su país garantizando el derecho de asistencia consular."),
        90 to ArticleMeta("Sanción a Autoridades por Incomunicación Ilegal", "Actos Procesales", "Se sancionará con destitución y pena de prisión al policía o funcionario que mantenga incomunicado a un detenido o dilate su puesta a disposición."),
        91 to ArticleMeta("Formalidades en la Recepción de Denuncias", "Actos Procesales", "Las denuncias verbales se harán constar en acta circunstanciada que firmará el denunciante previa lectura, entregándosele copia gratuita de inmediato."),
        92 to ArticleMeta("Obligación de Funcionarios de Denunciar Delitos", "Actos Procesales", "Todo servidor público que en el desempeño de su cargo conozca de hechos que puedan constituir delito tiene la obligación legal de denunciarlos al MP."),
        93 to ArticleMeta("Denuncia Anónima y Protocolos de Verificación", "Actos Procesales", "Las denuncias anónimas requerirán actos de verificación preliminar por la policía investigadora antes de judicializar la carpeta ante el juez de control."),
        94 to ArticleMeta("Trámite de Querella por Personas Morales", "Actos Procesales", "Las empresas y sociedades mercantiles formularán querella a través de apoderado legal con poder notarial general o especial para pleitos y cobranzas."),
        95 to ArticleMeta("Desistimiento de Querella y Extinción de la Acción", "Actos Procesales", "El desistimiento de la querella formulado por la víctima en delitos de querella necesaria extinguirá de inmediato la pretensión punitiva ministerial."),
        96 to ArticleMeta("Representación Coadyuvante de Víctimas Menores", "Actos Procesales", "Tratándose de niñas, niños y adolescentes víctimas, intervendrán obligatoriamente la Procuraduría de Protección de Menores y el Asesor Jurídico público."),
        97 to ArticleMeta("Derecho de las Víctimas a Impugnar Omisiones del MP", "Actos Procesales", "La víctima u ofendido podrá impugnar ante el Juez de Control las omisiones de la investigación, abstenciones de investigar o el archivo temporal del MP."),
        98 to ArticleMeta("Plazo de Diez Días para Impugnar Omisiones Ministeriales", "Actos Procesales", "La impugnación contra omisiones o archivo ministerial se promoverá dentro de los diez días siguientes a la notificación de la determinación ante el Juez."),
        99 to ArticleMeta("Audiencia de Control Judicial de Actuaciones del MP", "Actos Procesales", "El Juez de Control citará a una audiencia dentro de tres días oyendo a la víctima y al MP, pudiendo ordenar la reapertura forzosa de la investigación penal."),
        100 to ArticleMeta("Carácter Inapelable de la Orden de Reapertura Judicial", "Actos Procesales", "La resolución judicial que ordene al Ministerio Público continuar la investigación y agotar diligencias probatorias no admitirá recurso alguno."),
        101 to ArticleMeta("Reglas de Conducción Ética de las Partes", "Actos Procesales", "Las partes actuarán en el proceso con lealtad procesal y probidad, sancionándose la simulación de actos, la falsedad testimonial y el soborno judicial."),
        102 to ArticleMeta("Invalidez de Declaraciones Obtenidas con Tortura", "Actos Procesales", "Las declaraciones obtenidas mediante tortura, tratos crueles, inhumanos o degradantes carecen de todo valor probatorio y motivarán investigación penal oficiosa."),
        103 to ArticleMeta("Exclusión de Pruebas Ilícitas Derivadas (Árbol Envenenado)", "Actos Procesales", "Toda prueba que provenga directa o indirectamente de una violación a derechos fundamentales será excluida de plano del debate en juicio oral."),
        104 to ArticleMeta("Práctica de Diligencias de Reconstrucción de Hechos", "Actos Procesales", "La reconstrucción judicial de hechos se desahogará con intervención de peritos y testigos asegurando la preservación de la seguridad de las partes."),
        105 to ArticleMeta("Sujetos del Procedimiento Penal Acusatorio", "Sujetos Procesales", "Son sujetos del procedimiento: la víctima u ofendido, el asesor jurídico, el imputado, el defensor, el Ministerio Público, la policía y el órgano jurisdiccional."),
        106 to ArticleMeta("Reserva de Identidad y Protección a Sujetos Vulnerables", "Sujetos Procesales", "En casos de trata de personas, secuestro o delitos sexuales, se mantendrá en reserva la identidad y domicilio de la víctima y de los testigos en riesgo."),
        107 to ArticleMeta("Deber de Auxilio a Sujetos Procesales con Discapacidad", "Sujetos Procesales", "A las personas con discapacidad auditiva, visual o motriz se les garantizarán los apoyos técnicos, formatos accesibles e intérpretes de lengua de señas."),
        108 to ArticleMeta("Concepto Legal de Víctima y Ofendido", "Sujetos Procesales", "Se considera víctima al sujeto pasivo que reciente sobre su persona el delito; ofendido a la persona física o moral titular del bien jurídico lesionado."),
        109 to ArticleMeta("Derechos Fundamentales de la Víctima u Ofendido", "Sujetos Procesales", "Catálogo taxativo de derechos: a ser informada de sus derechos; contar con asesor jurídico gratuito; recibir atención médica urgente; y obtener reparación integral."),
        110 to ArticleMeta("Intervención y Facultades del Asesor Jurídico", "Sujetos Procesales", "El asesor jurídico orientará y representará legalmente a la víctima en todas las audiencias penales con facultades para ofrecer pruebas y apelar."),
        111 to ArticleMeta("Obligatoriedad de Designar Asesor Jurídico Público", "Sujetos Procesales", "Si la víctima no cuenta con abogado particular, el Estado le designará forzosamente un Asesor Jurídico Público especializado desde la primera diligencia."),
        112 to ArticleMeta("Concepto y Condición Procesal del Imputado", "Sujetos Procesales", "Se denominará imputado a quien sea señalado por el MP como posible autor o partícipe de un hecho delictivo; acusado al formalmente acusado; y sentenciado al condenado."),
        113 to ArticleMeta("Derechos Fundamentales del Imputado", "Sujetos Procesales", "A que se presuma su inocencia; comunicarse inmediatamente con familiares y defensor; declarar o guardar silencio; contar con defensa técnica adecuada y no ser incomunicado."),
        114 to ArticleMeta("Declaración Voluntaria del Imputado en Audiencia", "Sujetos Procesales", "El imputado podrá rendir su declaración en cualquier momento de la audiencia asistido por su defensor, pudiendo contestar preguntas o reservarse."),
        115 to ArticleMeta("Designación Libre de Defensor Técnico", "Sujetos Procesales", "El imputado podrá designar libremente a un defensor particular con cédula profesional desde el momento de su captura o solicitar defensor público."),
        116 to ArticleMeta("Requisitos Obligatorios para Ejercer como Defensor", "Sujetos Procesales", "Para fungir como defensor se requiere contar con título y cédula profesional de licenciado en derecho debidamente registrados ante el tribunal."),
        117 to ArticleMeta("Obligaciones y Facultades del Abogado Defensor", "Sujetos Procesales", "Entrevistar al imputado en privado; conocer los registros ministeriales; ofrecer pruebas pertinentes; formular alegatos y promover los recursos procedentes."),
        118 to ArticleMeta("Incompatibilidad de Defensa con Intereses Contrapuestos", "Sujetos Procesales", "Un mismo defensor no podrá representar a dos o más imputados en la misma causa cuando existan intereses encontrados o inculpaciones mutuas."),
        119 to ArticleMeta("Renuncia y Abandono Injustificado de la Defensa", "Sujetos Procesales", "El defensor no podrá renunciar al cargo sin causa justificada y continuará desempeñándolo hasta en tanto acepte el nuevo defensor particular o público."),
        120 to ArticleMeta("Sanción por Abandono de Defensa Técnica", "Sujetos Procesales", "Al abogado que abandone la defensa sin aviso previo dejando al imputado en estado de indefensión se le impondrá multa e inhabilitación profesional."),
        121 to ArticleMeta("Garantía de Confidencialidad Defensor-Imputado", "Sujetos Procesales", "Las comunicaciones y entrevistas privadas entre el imputado y su defensor son inviolables y no podrán ser intervenidas ni utilizadas como prueba."),
        122 to ArticleMeta("Nombramiento de Defensor Público de Oficio", "Sujetos Procesales", "El Instituto Federal de Defensoría Pública o las defensorías locales proveerán defensores capacitados de inmediato a todo imputado que carezca de defensa."),
        123 to ArticleMeta("Derecho a Sustituir al Defensor en Cualquier Etapa", "Sujetos Procesales", "El imputado podrá revocar la designación de su defensor y nombrar a otro en cualquier etapa del proceso penal sin perjuicio de la continuidad procesal."),
        124 to ArticleMeta("Defensa Común en Coautoría sin Conflicto", "Sujetos Procesales", "Dos o más coimputados podrán tener un solo defensor siempre que sus estrategias de descargo sean armónicas y no se atribuyan culpas recíprocas."),
        125 to ArticleMeta("Acceso del Defensor a Peritajes Oficiales", "Sujetos Procesales", "El defensor tiene derecho a designar peritos independientes para que asistan y dictaminen en diligencias científicas ministeriales o judiciales."),
        126 to ArticleMeta("Indemnización por Error Judicial en Defensa Negada", "Sujetos Procesales", "Si el imputado fuere condenado habiéndosele negado asistencia de defensor letrado, el Estado será condenado a reparar los daños por responsabilidad patrimonial."),
        127 to ArticleMeta("Facultades Constitucionales del Ministerio Público", "Sujetos Procesales", "Compete al Ministerio Público conducir la investigación penal, coordinar a las policías y a los servicios periciales, y ejercer la acción penal pública."),
        128 to ArticleMeta("Principios Rectores de la Actuación Ministerial", "Sujetos Procesales", "El Ministerio Público ejercerá sus atribuciones bajo los principios de legalidad, objetividad, eficiencia, profesionalismo, honradez y respeto a los derechos humanos."),
        129 to ArticleMeta("Deber de Objetividad y Carga Probatoria Ministerial", "Sujetos Procesales", "La carga de probar la culpabilidad del acusado corresponde al Ministerio Público; asimismo investigará con igual diligencia los hechos que extingan la responsabilidad."),
        130 to ArticleMeta("Carga Probatoria Exclusiva de la Acusación", "Sujetos Procesales", "El imputado no está obligado a probar su inocencia; cualquier duda razonable sobre su responsabilidad penal operará a su favor decretándose su absolución."),
        131 to ArticleMeta("Obligaciones Taxativas del Ministerio Público", "Sujetos Procesales", "Vigilar que en toda investigación se cumplan los derechos humanos; ordenar la recolección de indicios; preservar la escena; formular imputación y acusación formal."),
        132 to ArticleMeta("Obligaciones y Deberes de los Cuerpos de Policía", "Sujetos Procesales", "Recibir denuncias; practicar inspecciones; detener en flagrancia inmediata; preservar el lugar de los hechos y garantizar la integridad de las evidencias."),
        133 to ArticleMeta("Competencia Jurisdiccional de Control y Juicio", "Sujetos Procesales", "El Juez de Control resolverá la legalidad de detenciones y medidas cautelares; el Tribunal de Enjuiciamiento dictará el fallo definitivo de culpabilidad."),
        134 to ArticleMeta("Deberes Judiciales de Imparcialidad y Respeto", "Sujetos Procesales", "Los jueces resolverán con absoluta independencia judicial y perspectiva de derechos humanos, libres de presiones políticas, mediáticas o jerárquicas."),
        135 to ArticleMeta("Auxiliares de las Partes y Consultores Técnicos", "Sujetos Procesales", "Las partes podrán auxiliarse de consultores técnicos en ciencias o artes forenses para asistirlos en el interrogatorio pericial en audiencias orales."),
        136 to ArticleMeta("Intervención de Peritos Oficiales e Independientes", "Sujetos Procesales", "Los peritos emitirán sus dictámenes bajo juramento de verdad y deberán comparecer personalmente al juicio oral a sustentar sus conclusiones científicas."),
        137 to ArticleMeta("Medidas de Protección para la Víctima durante Investigación", "Medidas de Protección", "El MP ordenará de oficio: prohibición de acercarse a la víctima; separación inmediata del agresor del domicilio conyugal; y entrega de objetos personales."),
        138 to ArticleMeta("Ratificación Judicial de Medidas de Protección", "Medidas de Protección", "Las medidas de protección que impliquen desalojo del imputado deberán ser ratificadas por el Juez de Control dentro de las 48 horas siguientes."),
        139 to ArticleMeta("Auxilio Policial Permanente para Víctimas", "Medidas de Protección", "La policía proporcionará custodia domiciliaria inmediata o rondines periódicos a víctimas que enfrenten riesgo grave de violencia feminicida o amenazas."),
        140 to ArticleMeta("Providencias Precautorias para Restitución de Derechos", "Medidas Cautelares", "El juez podrá ordenar el embargo precautorio de bienes y la inmovilización de cuentas bancarias para garantizar la reparación del daño a la víctima."),
        141 to ArticleMeta("Formas de Conducción del Imputado al Proceso", "Medidas Cautelares", "Para conducir al imputado a la audiencia inicial se utilizarán: I. Citatorio judicial; II. Orden de comparecencia por la fuerza pública; y III. Orden de aprehensión."),
        142 to ArticleMeta("Procedencia de la Orden de Aprehensión Judicial", "Medidas Cautelares", "El juez librará orden de aprehensión a solicitud del MP cuando exista denuncia de hecho delictivo con pena privativa de libertad y riesgo de fuga acreditado."),
        143 to ArticleMeta("Trámite Electrónico y Reserva de la Orden de Aprehensión", "Medidas Cautelares", "La solicitud de orden de aprehensión se formulará en audiencia privada o por medios electrónicos seguros con resolución judicial en 24 horas."),
        144 to ArticleMeta("Ejecución Inmediata de la Orden de Aprehensión", "Medidas Cautelares", "Ejecutada la aprehensión por la policía, el imputado será puesto sin demora a disposición del Juez de Control en el centro penitenciario correspondiente."),
        145 to ArticleMeta("Cancelación Judicial de Órdenes de Aprehensión", "Medidas Cautelares", "El Ministerio Público podrá solicitar la cancelación de la orden de aprehensión antes de su ejecución si aparecen datos que desvirtúen la imputación."),
        146 to ArticleMeta("Supuestos Constitucionales de Flagrancia Estricta", "Detención", "Se podrá detener a una persona sin orden judicial en flagrancia: en el momento mismo de cometer el delito (I); o inmediatamente después de cometerlo perseguido materialmente o señalado con rastros (II)."),
        147 to ArticleMeta("Detención Ciudadana en Caso de Flagrancia", "Detención", "Cualquier persona puede detener al presunto delincuente en flagrancia debiendo entregarlo inmediatamente y sin demora a la autoridad policial más cercana."),
        148 to ArticleMeta("Registro Obligatorio de Detención y Puesta a Disposición", "Detención", "La policía inscribirá la captura de inmediato en el Registro Nacional de Detenciones y pondrá al detenido a disposición del MP sin dilación injustificada."),
        149 to ArticleMeta("Control de Plazos de Retención Ministerial (48 Horas)", "Detención", "El Ministerio Público examinará las condiciones de la flagrancia y retendrá al detenido por un plazo máximo de 48 horas (o 96 horas en delincuencia organizada)."),
        150 to ArticleMeta("Supuesto Excepcional de Caso Urgente Ministerial", "Detención", "Sólo en casos urgentes el MP podrá ordenar por escrito la detención de una persona si concurren: delito grave; riesgo inminente de sustracción; y que por hora o lugar no pueda acudir ante juez."),
        151 to ArticleMeta("Requisitos de Fundamentación en el Caso Urgente", "Detención", "La orden ministerial de caso urgente debe fundar y motivar con datos fácticos precisos la imposibilidad de ocurrir ante el juzgador de control."),
        152 to ArticleMeta("Calificación de Legalidad del Caso Urgente por el Juez", "Detención", "El Juez de Control calificará en la audiencia inicial si la detención por caso urgente cumplió con los requisitos constitucionales, decretando la libertad si fue ilegal."),
        153 to ArticleMeta("Reglas Generales y Fines de las Medidas Cautelares", "Medidas Cautelares", "Asegurar la presencia del imputado en el procedimiento; garantizar la seguridad de la víctima, ofendido o testigos; o evitar la obstaculización del proceso penal."),
        154 to ArticleMeta("Audiencia para el Debate de Medidas Cautelares", "Medidas Cautelares", "Las medidas cautelares se discutirán y resolverán en audiencia contradictoria tras formularse la imputación o vincularse a proceso penal."),
        155 to ArticleMeta("Catálogo Taxativo de Tipos de Medidas Cautelares", "Medidas Cautelares", "I. Presentación periódica; II. Embargo; III. Inmovilización de cuentas; IV. Prohibición de salir del país; V. Separación del domicilio; VI. Prisión preventiva justificada; y demás de las fracciones I a XIV."),
        156 to ArticleMeta("Criterios de Proporcionalidad y Menor Lesividad", "Medidas Cautelares", "El juzgador aplicará el principio de proporcionalidad eligiendo la medida menos lesiva indispensable para salvaguardar los fines del proceso penal."),
        157 to ArticleMeta("Supervisión de Medidas Cautelares en Libertad", "Medidas Cautelares", "La Unidad de Medidas Cautelares supervisará el cumplimiento de las medidas impuestas en libertad rindiendo informes periódicos al juez."),
        158 to ArticleMeta("Evaluación Técnica de Riesgos Procesales", "Medidas Cautelares", "La Unidad especializada evaluará el riesgo de fuga, arraigo familiar y laboral del imputado entregando dictamen técnico imparcial al juez."),
        159 to ArticleMeta("Fijación de Caución Económica y Garantías", "Medidas Cautelares", "Cuando se imponga fianza económica, el monto se tasará atendiendo a la capacidad financiera real del imputado sin que pueda ser confiscatoria."),
        160 to ArticleMeta("Medida de Localizador Electrónico (Brazalete)", "Medidas Cautelares", "El juez podrá autorizar el uso de brazalete electrónico con GPS para monitorear el perímetro de movilidad del imputado en libertad condicional."),
        161 to ArticleMeta("Revisión de Medidas Cautelares por Hecho Nuevo", "Medidas Cautelares", "Las partes podrán solicitar en cualquier momento la modificación, sustitución o cancelación de las medidas cautelares impuestas si cambian las condiciones."),
        162 to ArticleMeta("Trámite Incidental de Sustitución de Medidas", "Medidas Cautelares", "Promovida la revisión, el juez citará a una audiencia dentro de las 48 horas siguientes para escuchar a las partes y resolver de plano."),
        163 to ArticleMeta("Incumplimiento Injustificado de Medidas Cautelares", "Medidas Cautelares", "Si el imputado incumple la medida impuesta sin justificación legítima, el juez ordenará su reaprehensión y podrá agravar la cautelar imponiendo prisión."),
        164 to ArticleMeta("Reglas de Supervisión a Personas con Adicciones", "Medidas Cautelares", "Tratándose de medidas que impongan tratamiento contra adicciones, las instituciones de salud reportarán quincenalmente la adherencia terapéutica."),
        165 to ArticleMeta("Límite Temporal Máximo de la Prisión Preventiva (2 Años)", "Medidas Cautelares", "La prisión preventiva no podrá exceder del tiempo fijado por la ley, y en ningún caso será superior a dos años salvo demora atribuible a la defensa."),
        166 to ArticleMeta("Revisión Forzosa al Cumplirse Dos Años de Prisión", "Medidas Cautelares", "Vencido el plazo de dos años de prisión preventiva sin sentencia, el imputado será puesto en libertad inmediata o sujeta a medidas cautelares no privativas."),
        167 to ArticleMeta("Procedencia de la Prisión Preventiva Oficiosa", "Medidas Cautelares", "El juez ordenará prisión preventiva de oficio exclusivamente en los delitos taxativamente enumerados en el Artículo 19 constitucional DOF."),
        168 to ArticleMeta("Peligro de Sustracción del Imputado de la Justicia", "Medidas Cautelares", "Para decidir el peligro de fuga el juez evaluará: arraigo en el lugar del juicio; falsedad en domicilio; y facilidades económicas para abandonar el país."),
        169 to ArticleMeta("Peligro de Obstaculización del Desarrollo del Juicio", "Medidas Cautelares", "Se presumirá obstaculización si existen datos de que el imputado ha intentado intimidar a testigos, destruir documentos o inducir falsedad."),
        170 to ArticleMeta("Riesgo para la Seguridad de la Víctima o Testigos", "Medidas Cautelares", "El juez ponderará las amenazas previas, el uso de armas o los antecedentes de violencia física para imponer prisión preventiva justificada."),
        171 to ArticleMeta("Cancelación de Medidas Cautelares por Sobreseimiento", "Medidas Cautelares", "Decretado el sobreseimiento o dictada sentencia absolutoria, cesarán de pleno derecho todas las medidas cautelares ordenándose la libertad inmediata."),
        172 to ArticleMeta("Prisión Domiciliaria como Medida Cautelar Especial", "Medidas Cautelares", "El juez de control podrá ordenar resguardo domiciliario con custodia policial a personas de edad avanzada o mujeres en estado de lactancia."),
        173 to ArticleMeta("Medidas de Protección Especiales para Menores Infractores", "Medidas Cautelares", "A los adolescentes imputados no se les aplicará prisión preventiva de adultos sino medidas especiales de la Ley Nacional del Sistema Integral."),
        174 to ArticleMeta("Cancelación de Fichas Dactilares por Absolución", "Medidas Cautelares", "Dictada la absolución firme, se ordenará la destrucción de registros biométricos, fotografías e informes cautelares del imputado."),
        175 to ArticleMeta("Indemnización por Prisión Preventiva Injustificada", "Medidas Cautelares", "Quien sufra prisión preventiva y sea absuelto por inexistencia del delito tendrá derecho a reclamar indemnización patrimonial ante el Estado."),
        176 to ArticleMeta("Prohibición de Comunicar Medidas a Terceros Ajenos", "Medidas Cautelares", "Las actuaciones sobre medidas cautelares se conservarán en registro reservado para salvaguarda de la presunción de inocencia del justiciable."),
        177 to ArticleMeta("Notificación Inmediata al Centro Penitenciario", "Medidas Cautelares", "La orden de libertad dictada por el juez se comunicará de inmediato al director del centro penitenciario para su ejecución sin más trámite."),
        178 to ArticleMeta("Reglas Cautelares en Concurso de Delitos", "Medidas Cautelares", "En concurso de delitos se valorará la gravedad acumulada de las conductas para graduar la pertinencia de medidas cautelares privativas."),
        179 to ArticleMeta("Audiencias Cautelares en Días Inhábiles", "Medidas Cautelares", "Los jueces de control de guardia desahogarán audiencias de medidas cautelares de manera continua durante fines de semana y días feriados."),
        180 to ArticleMeta("Revisión de Medidas tras Acuerdos Reparatorios", "Medidas Cautelares", "Celebrado un acuerdo reparatorio con plan de pagos diferido, el juez sustituirá la prisión preventiva por medidas cautelares no privativas."),
        181 to ArticleMeta("Facultades de la Policía en Ejecución Cautelar", "Medidas Cautelares", "La policía procesal está facultada para vigilar el cumplimiento de las restricciones perimetrales y auxiliar de inmediato a la víctima en alarmas."),
        182 to ArticleMeta("Archivo del Expediente Cautelar tras la Condena", "Medidas Cautelares", "Pronunciada sentencia condenatoria ejecutoria, el cuaderno de medidas cautelares se remitirá al Juez de Ejecución Penal para los efectos legales."),
        183 to ArticleMeta("Principios Rectores de las Soluciones Alternas", "Justicia Restaurativa", "Las soluciones alternas se fundan en la justicia restaurativa, voluntariedad, confidencialidad, imparcialidad y reparación expedita del daño a la víctima."),
        184 to ArticleMeta("Formas de Solución Alterna del Procedimiento", "Justicia Restaurativa", "Son formas de solución alterna: I. Los acuerdos reparatorios; y II. La suspensión condicional del proceso a prueba."),
        185 to ArticleMeta("Forma de Terminación Anticipada: Procedimiento Abreviado", "Justicia Restaurativa", "El procedimiento abreviado es una forma de terminación anticipada que permite dictar sentencia pronta mediante reconocimiento de culpabilidad y rebaja de pena."),
        186 to ArticleMeta("Procedencia Taxativa de los Acuerdos Reparatorios", "Justicia Restaurativa", "Proceden en: I. Delitos perseguibles por querella; II. Delitos culposos; y III. Delitos patrimoniales cometidos sin violencia sobre las personas."),
        187 to ArticleMeta("Improcedencia de Acuerdos en Delitos Graves", "Justicia Restaurativa", "No proceden acuerdos reparatorios en homicidio doloso, secuestro, violación, violencia familiar o cuando el imputado haya incumplido acuerdos previos."),
        188 to ArticleMeta("Oportunidad Procesal para Celebrar Acuerdos", "Justicia Restaurativa", "Los acuerdos reparatorios podrán celebrarse desde la presentación de la denuncia hasta antes de dictarse el auto de apertura a juicio oral."),
        189 to ArticleMeta("Efectos Extintivos del Cumplimiento de Acuerdos", "Justicia Restaurativa", "El cumplimiento íntegro de las obligaciones pactadas en el acuerdo reparatorio extinguirá la acción penal decretándose el sobreseimiento total."),
        190 to ArticleMeta("Incumplimiento de Acuerdos y Continuación Procesal", "Justicia Restaurativa", "Si el imputado incumple sin causa justificada las obligaciones del acuerdo, se revocará de inmediato continuándose con el procedimiento penal ordinario."),
        191 to ArticleMeta("Concepto y Procedencia de la Suspensión Condicional", "Justicia Restaurativa", "Planteamiento del MP o imputado mediante plan detallado de reparación del daño y sometimiento a condiciones durante un período de prueba de 6 meses a 3 años."),
        192 to ArticleMeta("Requisitos para Otorgar la Suspensión Condicional", "Justicia Restaurativa", "Que el auto de vinculación se haya dictado por delito cuya pena media aritmética no exceda de cinco años y que no exista oposición fundada de la víctima."),
        193 to ArticleMeta("Oportunidad para Solicitar la Suspensión Condicional", "Justicia Restaurativa", "Podrá solicitarse una vez dictado el auto de vinculación a proceso y hasta antes de que se dicte el auto de apertura a juicio oral."),
        194 to ArticleMeta("Plan de Reparación del Daño Económico", "Justicia Restaurativa", "El imputado propondrá un plan de pagos e indemnizaciones a favor de la víctima, garantizando su solvencia y cumplimiento puntual."),
        195 to ArticleMeta("Condiciones a Cumplir en Período de Prueba", "Justicia Restaurativa", "Residir en lugar determinado; abstenerse de consumir drogas o alcohol; aprender un oficio; someterse a tratamiento médico; y no acercarse a la víctima."),
        196 to ArticleMeta("Trámite en Audiencia y Resolución Judicial", "Justicia Restaurativa", "El Juez de Control escuchará a las partes en audiencia, fijará las condiciones definitivas y el plazo de prueba notificando a la Unidad de Supervisión."),
        197 to ArticleMeta("Supervisión de Condiciones por la Autoridad Especializada", "Justicia Restaurativa", "La Unidad de Supervisión vigilará periódicamente que el imputado cumpla las condiciones impuestas reportando cualquier irregularidad al juez."),
        198 to ArticleMeta("Revocación de la Suspensión Condicional", "Justicia Restaurativa", "Si el imputado incumple las condiciones o es condenado por nuevo delito doloso, el juez revocará el beneficio y se continuará con el proceso penal."),
        199 to ArticleMeta("Extinción de la Acción Penal y Sobreseimiento", "Justicia Restaurativa", "Transcurrido el plazo de prueba sin que la suspensión haya sido revocada, el juez decretará de oficio la extinción penal y sobreseimiento firme."),
        200 to ArticleMeta("Efectos Inmutables del Sobreseimiento Cumplido", "Justicia Restaurativa", "El sobreseimiento firme cancelará antecedentes penales y tendrá plenos efectos de sentencia absolutoria con calidad de cosa juzgada."),
        201 to ArticleMeta("Requisitos de Procedencia del Procedimiento Abreviado", "Procedimiento Abreviado", "I. Que lo solicite el MP; II. Que la víctima no se oponga fundadamente; III. Que el imputado reconozca estar informado de su derecho a juicio oral; y IV. Acepte los hechos de la acusación."),
        202 to ArticleMeta("Oportunidad y Margen de Reducción de Penas", "Procedimiento Abreviado", "El MP podrá solicitar la reducción de hasta una mitad de la pena mínima en delitos culposos o no graves, y de hasta un tercio en delitos dolosos."),
        203 to ArticleMeta("Consentimiento Informado del Acusado", "Procedimiento Abreviado", "El juez verificará personalmente que el imputado renuncie a juicio oral de forma libre, voluntaria y con asistencia previa de su defensor letrado."),
        204 to ArticleMeta("Oposición Fundada de la Víctima u Ofendido", "Procedimiento Abreviado", "La víctima sólo podrá oponerse cuando no se garantice la reparación integral del daño conforme a los estándares de prueba acreditados."),
        205 to ArticleMeta("Trámite Concentrado de la Audiencia Abreviada", "Procedimiento Abreviado", "El MP expondrá la acusación y medios de convicción; la defensa y el acusado aceptarán los hechos; y el juez resolverá de inmediato dictando sentencia."),
        206 to ArticleMeta("Contenido de la Sentencia en Procedimiento Abreviado", "Procedimiento Abreviado", "El juez valorará los datos de prueba de la carpeta; no podrá imponer pena superior a la solicitada por el MP y condenará a la reparación del daño."),
        207 to ArticleMeta("Recurso de Apelación contra Sentencia Abreviada", "Procedimiento Abreviado", "La sentencia definitiva dictada en procedimiento abreviado sólo podrá ser apelada por estimación errónea de penas o violación a garantías procesales."),
        208 to ArticleMeta("Registro Nacional de Medidas y Salidas Alternas", "Justicia Restaurativa", "El Poder Judicial llevará un registro digital nacional de todas las suspensiones y acuerdos para evitar que un mismo sujeto se beneficie indebidamente."),
        209 to ArticleMeta("Prohibición de Utilizar Aceptación en Juicio Oral", "Justicia Restaurativa", "Si no se admite el procedimiento abreviado, la aceptación de culpabilidad del imputado carecerá de todo valor y no podrá invocarse en juicio oral."),
        210 to ArticleMeta("Capacitación Obligatoria en Métodos Alternativos", "Justicia Restaurativa", "Los operadores del sistema penal recibirán certificación continua en facilitación de mecanismos alternativos de solución de controversias."),
        211 to ArticleMeta("Etapas del Procedimiento Penal Acusatorio", "Etapas Procesales", "I. Investigación (inicial desde la denuncia hasta formulación de imputación, y complementaria); II. Intermedia (preparación a juicio); y III. Juicio Oral."),
        212 to ArticleMeta("Deber General de Investigar los Delitos", "Investigación Penal", "El Ministerio Público y la policía iniciarán la investigación de oficio en cuanto tengan conocimiento de un delito que deba perseguirse de oficio."),
        213 to ArticleMeta("Objeto de la Investigación Penal Ministerial", "Investigación Penal", "Reunir datos de prueba que esclarezcan el hecho calificado como delito y sustenten la acusación o la inocencia del imputado."),
        214 to ArticleMeta("Principios Rectores de la Policía Investigadora", "Investigación Penal", "La policía actuará bajo la conducción del Ministerio Público respetando los derechos humanos y directrices periciales científicas."),
